int[] nummern = { 17, 4, 23, 8, 42, 15 };

Console.WriteLine(LineareSuche(nummern, 8));
Console.WriteLine(LineareSuche(nummern, 99));
// Ausgabe:
// 3
// -1

int LineareSuche(int[] a, int gesucht)
{
    for (int i = 0; i < a.Length; i++)
    {
        if (a[i] == gesucht)
        {
            return i;  // sofort fertig
        }
    }
    return -1;  // nichts gefunden
}

int[] a = { 3, 7, 12, 18, 23, 31, 40, 52 };
Console.WriteLine(BinaereSuche(a, 40)); // 6
Console.WriteLine(BinaereSuche(a, 5));  // -1

int BinaereSuche(int[] a, int gesucht)
{
    int links = 0;
    int rechts = a.Length - 1;
    while (links <= rechts)
    {
        int mitte = (links + rechts) / 2;
        if (a[mitte] == gesucht)
        {
            return mitte;
        }
        else if (a[mitte] < gesucht)
        {
            links = mitte + 1;
        }
        else
        {
            rechts = mitte - 1;
        }
    }
    return -1;
}

